#!/usr/bin/env python3
"""TokenGuard - LLM API 429 Prevention Engine"""

import time
import re
import hashlib
from collections import defaultdict
from dataclasses import dataclass, field
from typing import Optional


@dataclass
class CheckResult:
    """Result from check() method"""
    action: str  # proceed/wait/fallback/block
    estimated_tokens: int
    wait_seconds: float = 0.0
    fallback_model: Optional[str] = None
    reason: str = ""


# Model quotas (tokens per minute)
MODEL_QUOTAS = {
    "gemini-3-flash": 1_000_000,
    "gemini-3-pro": 2_000_000,
    "claude-haiku": 50_000,
    "claude-sonnet": 200_000,
    "claude-opus": 200_000,
    "gpt-4o": 800_000,
    "deepseek": 1_000_000,
}

# Fallback hierarchy (cheaper/available alternatives)
MODEL_FALLBACKS = {
    "gemini-3-pro": "gemini-3-flash",
    "claude-opus": "claude-sonnet",
    "claude-sonnet": "claude-haiku",
    "gpt-4o": "deepseek",
}


class TokenGuard:
    """TokenGuard engine for preventing LLM API 429 errors."""

    def __init__(self, custom_quotas: Optional[dict] = None):
        """Initialize TokenGuard with optional custom model quotas."""
        self.model_quotas = {**MODEL_QUOTAS}
        if custom_quotas:
            self.model_quotas.update(custom_quotas)

        # Sliding window: model -> list of (timestamp, tokens)
        self.usage_windows: dict[str, list[tuple[float, int]]] = defaultdict(list)

        # Duplicate detection: prompt_hash -> list of timestamps
        self.prompt_history: dict[str, list[float]] = defaultdict(list)

        # Response cache: prompt_hash -> response
        self.response_cache: dict[str, str] = {}

        # 429 retry delays: model -> (timestamp, delay)
        self.retry_delays: dict[str, tuple[float, float]] = {}

        # Stats
        self.stats = {
            "total_checks": 0,
            "total_blocked": 0,
            "total_cached": 0,
            "total_fallbacks": 0,
        }

    def _estimate_tokens(self, prompt: str) -> int:
        """Estimate token count with CJK-aware counting."""
        if not prompt:
            return 0

        # CJK character ranges (simplified)
        cjk_pattern = re.compile(
            r'[\u4e00-\u9fff]'      # CJK Unified Ideographs
            r'|[\u3400-\u4dbf]'     # CJK Extension A
            r'|[\u20000-\u2a6df]'   # CJK Extension B (surrogate pairs)
            r'|[\uff00-\uffef]'     # Fullwidth forms
            r'|[\u3040-\u309f]'     # Hiragana
            r'|[\u30a0-\u30ff]'     # Katakana
            r'|[\xac00-\xd7af]'     # Hangul Syllables
        )

        cjk_count = len(cjk_pattern.findall(prompt))
        non_cjk_count = len(prompt) - cjk_count

        # CJK chars typically count as ~1.5-2 tokens, ASCII as ~0.25-0.5
        # Simplified: CJK = 2 tokens, ASCII = 1 char per 4 chars = 0.25 tokens
        estimated = (cjk_count * 2) + (non_cjk_count // 4 + 1)
        return max(estimated, 1)

