        """Remove entries older than 60 seconds from usage window."""
        cutoff = now - 60
        self.usage_windows[model] = [
            (ts, tokens) for ts, tokens in self.usage_windows[model]
            if ts > cutoff
        ]

    def _get_usage_in_window(self, model: str, now: float) -> int:
        """Get total tokens used in the last 60 seconds for a model."""
        self._clean_window(model, now)
        return sum(tokens for _, tokens in self.usage_windows[model])

    def _get_quota(self, model: str) -> int:
        """Get TPM quota for a model, defaulting to 100K."""
        return self.model_quotas.get(model, 100_000)

