        """Check if prompt is a duplicate. Returns (is_duplicate, count)."""
        prompt_hash = hashlib.md5(prompt.encode()).hexdigest()

        # Clean old entries (older than 60s)
        cutoff = now - 60
        self.prompt_history[prompt_hash] = [
            ts for ts in self.prompt_history[prompt_hash] if ts > cutoff
        ]

        count = len(self.prompt_history[prompt_hash])
        return count >= 3, count

    def _get_cached_response(self, prompt: str) -> Optional[str]:
        """Get cached response for prompt if exists."""
        prompt_hash = hashlib.md5(prompt.encode()).hexdigest()
        return self.response_cache.get(prompt_hash)

    def check(self, prompt: str, model: str) -> CheckResult:
        """Check if request should proceed, wait, fallback, or be blocked."""
        now = time.time()
        self.stats["total_checks"] += 1

        estimated_tokens = self._estimate_tokens(prompt)
        quota = self._get_quota(model)
        current_usage = self._get_usage_in_window(model, now)
        usage_ratio = current_usage / quota if quota > 0 else 1.0

        # Check for duplicate requests
        is_duplicate, dup_count = self._check_duplicate(prompt, now)
        if is_duplicate:
            self.stats["total_blocked"] += 1
            # Check if we have a cached response
            cached = self._get_cached_response(prompt)
            if cached:
                return CheckResult(
                    action="proceed",
                    estimated_tokens=0,
                    reason=f"Duplicate request ({dup_count}x), using cached response"
                )
            return CheckResult(
                action="block",
                estimated_tokens=estimated_tokens,
                reason=f"Duplicate request detected ({dup_count} times in 60s)"
            )

        # Check retry delay from 429
        if model in self.retry_delays:
            delay_ts, delay = self.retry_delays[model]
            remaining = delay - (now - delay_ts)
            if remaining > 0:
                return CheckResult(
                    action="wait",
                    estimated_tokens=estimated_tokens,
                    wait_seconds=remaining,
                    reason=f"429 retry delay: {remaining:.1f}s remaining"
                )

        # Check if request would exceed quota
        projected_usage = current_usage + estimated_tokens
        projected_ratio = projected_usage / quota if quota > 0 else 1.0

        # Block at >95% quota
        if projected_ratio > 0.95:
            self.stats["total_blocked"] += 1
            fallback = MODEL_FALLBACKS.get(model)
            return CheckResult(
                action="block",
                estimated_tokens=estimated_tokens,
                fallback_model=fallback,
                reason=f"Quota exhausted ({usage_ratio*100:.1f}% used, would be {projected_ratio*100:.1f}%)"
            )

        # Wait at >80% quota
        if usage_ratio > 0.80:
            # Estimate time until enough quota is freed
            wait_seconds = max(1.0, (usage_ratio - 0.80) * 60)
            return CheckResult(
                action="wait",
                estimated_tokens=estimated_tokens,
                wait_seconds=wait_seconds,
                reason=f"High quota usage ({usage_ratio*100:.1f}%), waiting {wait_seconds:.1f}s"
            )

        # Suggest fallback if approaching limit
        if usage_ratio > 0.70:
            fallback = MODEL_FALLBACKS.get(model)
            return CheckResult(
                action="proceed",
                estimated_tokens=estimated_tokens,
                fallback_model=fallback,
                reason=f"Proceeding (quota at {usage_ratio*100:.1f}%), consider fallback"
            )

        return CheckResult(
            action="proceed",
            estimated_tokens=estimated_tokens,
            reason=f"OK (quota at {usage_ratio*100:.1f}%)"
        )

    def record_usage(self, tokens: int, model: str) -> None:
        """Record token usage for a model."""
        now = time.time()
        self.usage_windows[model].append((now, tokens))

    def cache_response(self, prompt: str, response: str) -> None:
        """Cache a response for a prompt."""
        prompt_hash = hashlib.md5(prompt.encode()).hexdigest()
        self.response_cache[prompt_hash] = response
        self.stats["total_cached"] += 1

    def record_429(self, model: str, retry_delay: Optional[float] = None) -> None:
        """Record a 429 error and its retry delay."""
        now = time.time()
        if retry_delay is None:
            retry_delay = 60.0  # Default 60s if not specified
        self.retry_delays[model] = (now, retry_delay)

    def status(self) -> dict:
        """Return current status including model quotas and stats."""
        now = time.time()
        models_status = {}

        for model in self.model_quotas:
            current = self._get_usage_in_window(model, now)
            quota = self.model_quotas[model]
            models_status[model] = {
                "quota": quota,
                "used": current,
                "available": max(0, quota - current),
                "usage_percent": round((current / quota) * 100, 2) if quota > 0 else 100,
            }

        # Clean up expired retry delays
        expired = [m for m, (ts, _) in self.retry_delays.items() if now - ts > 60]
        for m in expired:
            del self.retry_delays[m]

        return {
            "models": models_status,
            "stats": {
                **self.stats,
                "cached_prompts": len(self.response_cache),
                "tracked_prompts": len(self.prompt_history),
            },
            "retry_delays": {
                model: {"delay": delay, "remaining": max(0, delay - (now - ts))}
                for model, (ts, delay) in self.retry_delays.items()
            },
        }


